import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, Router as WouterRouter, useLocation, useRoute } from 'wouter';
import {
  Activity, ArrowDownToLine, ArrowLeftRight, ArrowUpFromLine, Boxes, Building2, ChevronDown,
  CircleAlert, ClipboardList, Command, Database, FileClock, FilePlus2, Gauge, KeyRound, LayoutDashboard,
  LogOut, Menu, PackageCheck, PackagePlus, Radio, RefreshCw, Search, Settings2, ShieldCheck, Siren,
  Truck, UserCog, Users, X, Zap,
} from 'lucide-react';
import {
  useLogin, useGetCurrentUser, useGetDashboard, getGetDashboardQueryKey, useGetInventory,
  useListBases, getListBasesQueryKey, useCreateBase, useUpdateBase, useDeleteBase,
  useListEquipmentTypes, getListEquipmentTypesQueryKey, useCreateEquipmentType, useUpdateEquipmentType, useDeleteEquipmentType,
  useListPurchases, getListPurchasesQueryKey, useCreatePurchase,
  useListTransfers, getListTransfersQueryKey, useCreateTransfer, useUpdateTransferStatus,
  useListAssignments, getListAssignmentsQueryKey, useCreateAssignment,
  useListExpenditures, getListExpendituresQueryKey, useCreateExpenditure,
  useListAuditLogs, useListUsers, getListUsersQueryKey, useCreateUser, useUpdateUser, useDeleteUser,
  setAuthTokenGetter,
} from '@workspace/api-client-react';
import { Category, Role, TransferStatus, type Base, type EquipmentType, type User } from '@workspace/api-client-react';

const queryClient = new QueryClient();
const AUTH_TOKEN_KEY = 'kristallball.auth.token';
const cn = (...items: Array<string | false | undefined>) => items.filter(Boolean).join(' ');
const fmt = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const dateOnly = (value?: string | null) => value ? new Date(value).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' }) : '—';
const categoryLabel = (value?: string) => value ? value.charAt(0) + value.slice(1).toLowerCase() : 'Unclassified';
const isUnauthorizedError = (error: unknown) =>
  typeof error === 'object' && error !== null && 'status' in error && (error as { status?: unknown }).status === 401;

setAuthTokenGetter(() => typeof window === 'undefined' ? null : window.localStorage.getItem(AUTH_TOKEN_KEY));

queryClient.getMutationCache().subscribe(event => {
  if (event.type !== 'updated' || event.action.type !== 'success' || event.mutation.options.mutationKey?.[0] !== 'login') return;
  const token = (event.mutation.state.data as { token?: unknown } | undefined)?.token;
  if (typeof token === 'string') window.localStorage.setItem(AUTH_TOKEN_KEY, token);
});

function Button({ children, className, variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'danger' | 'outline' }) {
  return (
    <button
      {...props}
      className={cn(
        'inline-flex items-center justify-center gap-2 rounded-md px-3 py-2 text-[12px] font-bold tracking-[.02em] disabled:cursor-not-allowed disabled:opacity-45',
        variant === 'primary' && 'bg-primary text-white shadow-sm hover:brightness-110',
        variant === 'ghost' && 'text-muted-foreground hover:bg-secondary hover:text-foreground',
        variant === 'danger' && 'bg-destructive text-destructive-foreground hover:brightness-110',
        variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary hover:text-primary',
        className
      )}
    >
      {children}
    </button>
  );
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="grid gap-1.5 text-[11px] font-bold uppercase tracking-[.12em] text-muted-foreground">{label}{children}{hint && <span className="font-normal normal-case tracking-normal opacity-75">{hint}</span>}</label>;
}

function SelectField({ value, onChange, options, label, placeholder = 'Select…' }: { value: string; onChange: (value: string) => void; options: Array<{ value: string; label: string }>; label: string; placeholder?: string }) {
  return <Field label={label}><select data-testid={`select-${label.toLowerCase().replaceAll(' ', '-')}`} value={value} onChange={e => onChange(e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 text-sm font-medium text-foreground outline-none focus:border-primary focus:ring-2 focus:ring-primary/20"><option value="">{placeholder}</option>{options.map(option => <option value={option.value} key={option.value}>{option.label}</option>)}</select></Field>;
}

function Modal({ title, eyebrow, onClose, children }: { title: string; eyebrow?: string; onClose: () => void; children: ReactNode }) {
  return <div className="fixed inset-0 z-40 grid place-items-center bg-[hsl(211_39%_14%/.55)] p-4 backdrop-blur-sm" onMouseDown={onClose}><div className="animate-rise w-full max-w-xl rounded-lg border border-border bg-card p-5 shadow-2xl" onMouseDown={e => e.stopPropagation()}><div className="mb-5 flex items-start justify-between gap-4"><div><p className="font-mono-ui text-[10px] font-bold uppercase tracking-[.2em] text-primary">{eyebrow || 'Operations record'}</p><h2 className="mt-1 font-display text-3xl uppercase leading-none text-foreground">{title}</h2></div><Button data-testid="button-close-modal" variant="ghost" onClick={onClose} aria-label="Close dialog"><X size={18} /></Button></div>{children}</div></div>;
}

function LoadingState({ label = 'Synchronizing command data' }: { label?: string }) {
  return <div className="grid gap-3">{[1, 2, 3].map(i => <div key={i} className="h-14 animate-pulse rounded-md bg-secondary/75" />)}<p data-testid="status-loading" className="font-mono-ui text-[10px] uppercase tracking-[.16em] text-muted-foreground">{label}…</p></div>;
}
function ErrorState({ onRetry, label = 'Data link unavailable' }: { onRetry?: () => void; label?: string }) {
  return <div data-testid="status-error" className="flex items-center justify-between gap-4 rounded-md border border-destructive/30 bg-destructive/5 p-4 text-sm"><span className="flex items-center gap-2 text-destructive"><CircleAlert size={17} />{label}</span>{onRetry && <Button variant="outline" onClick={onRetry} data-testid="button-retry"><RefreshCw size={14} />Retry</Button>}</div>;
}
function EmptyState({ title, detail }: { title: string; detail: string }) {
  return <div data-testid="status-empty" className="grid place-items-center rounded-md border border-dashed border-border bg-secondary/30 px-5 py-12 text-center"><div className="mb-3 grid h-11 w-11 place-items-center rounded-full bg-primary/10 text-primary"><Database size={20} /></div><h3 className="font-display text-2xl uppercase">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p></div>;
}

const navGroups = [
  { label: 'Command', items: [{ href: '/', label: 'Overview', icon: LayoutDashboard }, { href: '/inventory', label: 'Inventory', icon: Boxes }] },
  { label: 'Movement', items: [{ href: '/purchases', label: 'Purchases', icon: PackagePlus }, { href: '/transfers', label: 'Transfers', icon: ArrowLeftRight }, { href: '/assignments', label: 'Assignments', icon: ClipboardList }, { href: '/expenditures', label: 'Expenditures', icon: ArrowUpFromLine }] },
  { label: 'Control', items: [{ href: '/audit', label: 'Audit trail', icon: FileClock }] },
];
const adminNav = [{ href: '/admin/users', label: 'Users', icon: Users }, { href: '/admin/bases', label: 'Bases', icon: Building2 }, { href: '/admin/equipment', label: 'Equipment catalog', icon: PackageCheck }];

function Shell({ children, user }: { children: ReactNode; user?: User }) {
  const [open, setOpen] = useState(false);
  const [location, setLocation] = useLocation();
  const logout = () => {
    window.localStorage.removeItem(AUTH_TOKEN_KEY);
    queryClient.clear();
    setLocation('/login');
  };
  return <div className="scanline min-h-[100dvh] bg-background text-foreground">
    <aside className={cn('fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col border-r border-sidebar-border bg-sidebar px-4 py-5 text-sidebar-foreground transition-transform md:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="mb-8 flex items-center justify-between px-2"><Link href="/" data-testid="link-brand" className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center border border-sidebar-primary/50 bg-sidebar-primary text-sidebar-primary-foreground"><Command size={20} strokeWidth={2.5} /></span><span><strong className="font-display text-2xl uppercase leading-none tracking-wide">Kristallball</strong><small className="block font-mono-ui text-[9px] uppercase tracking-[.18em] text-sidebar-foreground/55">Asset operations</small></span></Link><Button variant="ghost" data-testid="button-close-sidebar" onClick={() => setOpen(false)} className="md:hidden text-sidebar-foreground"><X size={17} /></Button></div>
      <div className="mb-7 rounded-md border border-sidebar-border bg-sidebar-accent/40 p-3"><div className="flex items-center gap-2 font-mono-ui text-[9px] uppercase tracking-[.16em] text-sidebar-primary"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-sidebar-primary" />Secure channel live</div><p className="mt-2 text-xs text-sidebar-foreground/60">Command network / 04</p></div>
      <nav className="flex-1 space-y-6">{navGroups.map(group => <div key={group.label}><p className="mb-2 px-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/40">{group.label}</p><div className="space-y-0.5">{group.items.map(item => <Link data-testid={`link-nav-${item.label.toLowerCase()}`} href={item.href} onClick={() => setOpen(false)} key={item.href} className={cn('group flex items-center gap-3 rounded-md px-3 py-2.5 text-[13px] font-semibold text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground', location === item.href && 'bg-sidebar-primary font-bold text-sidebar-primary-foreground hover:bg-sidebar-primary hover:text-sidebar-primary-foreground')}><item.icon size={16} strokeWidth={location === item.href ? 2.4 : 1.8} /><span>{item.label}</span>{location === item.href && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-current" />}</Link>)}</div></div>)}{user?.role === Role.ADMIN && <div><p className="mb-2 px-3 font-mono-ui text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/40">Administration</p><div className="space-y-0.5">{adminNav.map(item => <Link data-testid={`link-nav-${item.label.toLowerCase()}`} href={item.href} onClick={() => setOpen(false)} key={item.href} className={cn('flex items-center gap-3 rounded-md px-3 py-2.5 text-[13px] font-semibold text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground', location === item.href && 'bg-sidebar-primary text-sidebar-primary-foreground')}><item.icon size={16} /><span>{item.label}</span></Link>)}</div></div>}</nav>
      <div className="border-t border-sidebar-border pt-4"><div className="flex items-center gap-3 px-2"><div className="grid h-8 w-8 place-items-center rounded-full bg-sidebar-primary font-mono-ui text-xs font-bold text-sidebar-primary-foreground">{user?.username?.slice(0, 2).toUpperCase() || 'OP'}</div><div className="min-w-0 flex-1"><p data-testid="text-current-user" className="truncate text-xs font-bold">{user?.username || 'Operator'}</p><p className="truncate font-mono-ui text-[9px] uppercase text-sidebar-foreground/45">{user?.role?.replaceAll('_', ' ') || 'Command staff'}</p></div><Button variant="ghost" data-testid="button-logout" onClick={logout} className="p-1.5 text-sidebar-foreground/55 hover:text-sidebar-primary"><LogOut size={15} /></Button></div></div>
    </aside>
    <div className="md:pl-[248px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-border bg-background/90 px-4 backdrop-blur-md md:px-8"><div className="flex items-center gap-3"><Button variant="ghost" data-testid="button-open-sidebar" onClick={() => setOpen(true)} className="p-2 md:hidden"><Menu size={20} /></Button><div className="hidden items-center gap-2 font-mono-ui text-[10px] uppercase tracking-[.18em] text-muted-foreground sm:flex"><Radio size={14} className="text-primary" /> Operations / <span className="text-foreground">{location === '/' ? 'Command overview' : location.slice(1).replaceAll('/', ' / ')}</span></div></div><div className="flex items-center gap-2"><span className="hidden font-mono-ui text-[10px] text-muted-foreground lg:inline">UTC {new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span><span className="grid h-8 w-8 place-items-center rounded-full border border-border bg-card text-primary"><ShieldCheck size={16} /></span></div></header><main className="mx-auto max-w-[1600px] p-4 md:p-8">{children}</main></div>
  </div>;
}

function SectionHeading({ kicker, title, detail, action }: { kicker: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 border-b border-border pb-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-mono-ui text-[10px] font-bold uppercase tracking-[.2em] text-primary">{kicker}</p><h1 data-testid={`heading-${title.toLowerCase().replaceAll(' ', '-')}`} className="mt-1 font-display text-4xl uppercase leading-none tracking-tight sm:text-5xl">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function Metric({ label, value, accent = 'primary', delta }: { label: string; value: number | string; accent?: 'primary' | 'accent' | 'orange' | 'green'; delta?: string }) {
  return <div data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="relative overflow-hidden rounded-md border border-border bg-card p-4"><div className={cn('absolute left-0 top-0 h-1 w-12', accent === 'primary' && 'bg-primary', accent === 'accent' && 'bg-accent', accent === 'orange' && 'bg-chart-3', accent === 'green' && 'bg-chart-4')} /><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-muted-foreground">{label}</p><p className="mt-2 font-display text-4xl">{typeof value === 'number' ? value.toLocaleString() : value}</p>{delta && <p className="mt-1 text-[11px] font-bold text-chart-4">{delta}</p>}</div>;
}

function FilterBar({ bases, equipment, base, setBase, equip, setEquip }: { bases?: Base[]; equipment?: EquipmentType[]; base: string; setBase: (v: string) => void; equip: string; setEquip: (v: string) => void }) {
  return <div className="mb-5 flex flex-wrap items-end gap-3 rounded-md border border-border bg-card p-3"><div className="flex items-center gap-2 px-1 pb-2 text-muted-foreground"><Search size={15} /><span className="font-mono-ui text-[10px] uppercase tracking-[.15em]">Scope</span></div><SelectField label="Base" value={base} onChange={setBase} options={(bases || []).map(b => ({ value: String(b.id), label: b.name }))} placeholder="All bases" /><SelectField label="Equipment" value={equip} onChange={setEquip} options={(equipment || []).map(e => ({ value: String(e.id), label: e.name }))} placeholder="All equipment" /></div>;
}

function Overview() {
  const [base, setBase] = useState(''); const [equip, setEquip] = useState('');
  const params = useMemo(() => ({ ...(base ? { baseId: Number(base) } : {}), ...(equip ? { equipmentTypeId: Number(equip) } : {}) }), [base, equip]);
  const dash = useGetDashboard(params, { query: { queryKey: getGetDashboardQueryKey(params) } });
  const bases = useListBases(); const equipment = useListEquipmentTypes();
  if (dash.isLoading) return <PageFrame><SectionHeading kicker="Command / live picture" title="Overview" detail="Calculated inventory posture across the operating network." /><LoadingState /></PageFrame>;
  if (dash.isError || !dash.data) return <PageFrame><SectionHeading kicker="Command / live picture" title="Overview" /><ErrorState onRetry={() => dash.refetch()} /></PageFrame>;
  const d = dash.data;
  return <PageFrame><SectionHeading kicker="Command / live picture" title="Overview" detail="Calculated inventory posture across the operating network." action={<div className="flex items-center gap-2 rounded-md border border-chart-4/30 bg-chart-4/5 px-3 py-2 font-mono-ui text-[10px] uppercase tracking-[.14em] text-chart-4"><span className="h-1.5 w-1.5 rounded-full bg-chart-4" />Live calculation</div>} /><FilterBar bases={bases.data} equipment={equipment.data} base={base} setBase={setBase} equip={equip} setEquip={setEquip} />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Closing balance" value={d.closingBalance} accent="accent" delta="Current network stock" /><Metric label="Opening balance" value={d.openingBalance} /><Metric label="Net movement" value={d.netMovement} accent="orange" delta={`${d.transfersIn} in / ${d.transfersOut} out`} /><Metric label="Utilized" value={d.assigned + d.expended} accent="green" delta={`${d.assigned} assigned · ${d.expended} expended`} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><ChartPanel title="Movement signal" kicker="Last 8 reporting periods"><TrendChart data={d.movementSeries} /></ChartPanel><ChartPanel title="Inventory mix" kicker="By category"><Donut data={d.inventoryByCategory} /></ChartPanel></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><div className="rounded-md border border-border bg-card"><div className="flex items-center justify-between border-b border-border p-4"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">Movement ledger</p><h2 className="font-display text-2xl uppercase">Balance equation</h2></div><Zap size={18} className="text-accent" /></div><div className="grid grid-cols-2 gap-px bg-border sm:grid-cols-4">{[['Purchases', d.purchases], ['Transfers in', d.transfersIn], ['Transfers out', -d.transfersOut], ['Expended', -d.expended]].map(([label, val]) => <div key={label as string} className="bg-card p-4"><p className="font-mono-ui text-[10px] uppercase text-muted-foreground">{label}</p><p className={cn('mt-2 font-mono-ui text-xl font-bold', Number(val) < 0 ? 'text-chart-3' : 'text-foreground')}>{Number(val) > 0 ? '+' : ''}{Number(val).toLocaleString()}</p></div>)}</div></div><ActivityList activities={d.recentActivity} /></div>
  </PageFrame>;
}

function ChartPanel({ title, kicker, children }: { title: string; kicker: string; children: ReactNode }) { return <div className="rounded-md border border-border bg-card p-4"><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">{kicker}</p><h2 className="mb-4 font-display text-2xl uppercase">{title}</h2>{children}</div>; }
function TrendChart({ data = [] }: { data?: Array<{ label: string; value: number; secondaryValue?: number }> }) { const vals = data.length ? data : [{ label: '—', value: 0 }]; const max = Math.max(...vals.map(x => Math.max(x.value, x.secondaryValue || 0)), 1); return <div data-testid="chart-movement" className="flex h-44 items-end gap-2 border-b border-l border-border px-3 pb-0 pt-4">{vals.map((item, i) => <div className="group flex h-full flex-1 items-end gap-1" key={`${item.label}-${i}`}><div title={`${item.label}: ${item.value}`} className="w-1/2 rounded-t-sm bg-primary/85 group-hover:bg-primary" style={{ height: `${Math.max(5, item.value / max * 100)}%` }} /><div title={`${item.label}: ${item.secondaryValue || 0}`} className="w-1/2 rounded-t-sm bg-accent/80 group-hover:bg-accent" style={{ height: `${Math.max(5, (item.secondaryValue || 0) / max * 100)}%` }} /><span className="absolute translate-y-6 font-mono-ui text-[8px] text-muted-foreground">{item.label}</span></div>)}</div>; }
function Donut({ data = [] }: { data?: Array<{ label: string; value: number }> }) { const total = data.reduce((a, b) => a + b.value, 0); return <div className="flex min-h-[176px] items-center gap-5">{data.length ? <div className="relative grid h-36 w-36 shrink-0 place-items-center rounded-full" style={{ background: `conic-gradient(hsl(var(--primary)) 0 ${total ? (data[0]?.value / total * 100) : 0}%, hsl(var(--accent)) 0 ${total ? ((data[0]?.value + (data[1]?.value || 0)) / total * 100) : 0}%, hsl(var(--chart-3)) 0 100%)` }}><div className="grid h-24 w-24 place-items-center rounded-full bg-card"><span className="font-display text-3xl">{total.toLocaleString()}</span></div></div> : <EmptyState title="No category signal" detail="Category data will appear after stock is recorded." />}<div className="space-y-3">{data.map((item, i) => <div className="flex items-center gap-2" key={item.label}><span className={cn('h-2 w-2 rounded-full', i === 0 ? 'bg-primary' : i === 1 ? 'bg-accent' : 'bg-chart-3')} /><span className="text-xs font-semibold">{item.label}</span><span className="ml-auto font-mono-ui text-xs text-muted-foreground">{item.value.toLocaleString()}</span></div>)}</div></div>; }
function ActivityList({ activities = [] }: { activities?: Array<{ id: number; username: string; action: string; entityType: string; details: string; createdAt: string }> }) { return <div className="rounded-md border border-border bg-card"><div className="border-b border-border p-4"><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">Security feed</p><h2 className="font-display text-2xl uppercase">Recent activity</h2></div>{activities.length ? <div>{activities.slice(0, 5).map(item => <div data-testid={`activity-${item.id}`} className="flex gap-3 border-b border-border p-3 last:border-0" key={item.id}><div className="mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-full bg-primary/10 text-primary"><Activity size={13} /></div><div className="min-w-0"><p className="text-xs font-bold">{item.action} <span className="font-normal text-muted-foreground">/ {item.entityType}</span></p><p className="truncate text-[11px] text-muted-foreground">{item.details}</p><p className="mt-1 font-mono-ui text-[9px] uppercase text-muted-foreground/70">{item.username} · {fmt(item.createdAt)}</p></div></div>)}</div> : <div className="p-4"><EmptyState title="No activity" detail="Audit events will surface here as the network changes." /></div>}</div>; }

function PageFrame({ children }: { children: ReactNode }) { return <div className="animate-rise">{children}</div>; }

function Inventory() { const [base, setBase] = useState(''); const [equip, setEquip] = useState(''); const params = useMemo(() => ({ ...(base ? { baseId: Number(base) } : {}), ...(equip ? { equipmentTypeId: Number(equip) } : {}) }), [base, equip]); const q = useGetInventory(params, { query: { queryKey: ['/api/inventory', params] } }); const bases = useListBases(); const eq = useListEquipmentTypes(); return <PageFrame><SectionHeading kicker="Command / stock position" title="Inventory" detail="Calculated availability, assigned stock, and consumption by base." /><FilterBar bases={bases.data} equipment={eq.data} base={base} setBase={setBase} equip={equip} setEquip={setEquip} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : q.data?.length ? <DataTable columns={['Base', 'Equipment', 'Category', 'Available', 'Assigned', 'Expended']} rows={q.data.map((r, i) => <tr data-testid={`row-inventory-${r.baseId}-${r.equipmentTypeId}`} key={`${r.baseId}-${r.equipmentTypeId}`}><td className="font-bold">{r.baseName}</td><td>{r.equipmentName}</td><td><CategoryBadge value={r.category} /></td><td className="font-mono-ui font-bold text-primary">{r.available.toLocaleString()}</td><td className="font-mono-ui">{r.assigned.toLocaleString()}</td><td className="font-mono-ui text-muted-foreground">{r.expended.toLocaleString()}</td></tr>)} /> : <EmptyState title="Inventory is clear" detail="No stock rows match the current scope." />}</PageFrame>; }
function CategoryBadge({ value }: { value: string }) { return <span className="inline-flex rounded-sm border border-primary/20 bg-primary/5 px-2 py-1 font-mono-ui text-[9px] uppercase tracking-[.12em] text-primary">{categoryLabel(value)}</span>; }
function DataTable({ columns, rows }: { columns: string[]; rows: ReactNode[] }) { return <div className="overflow-x-auto rounded-md border border-border bg-card"><table className="w-full min-w-[680px] text-left text-xs"><thead className="bg-secondary/55 font-mono-ui text-[10px] uppercase tracking-[.12em] text-muted-foreground"><tr>{columns.map(c => <th className="px-4 py-3" key={c}>{c}</th>)}</tr></thead><tbody className="divide-y divide-border">{rows}</tbody></table></div>; }

function RecordPage({ kind }: { kind: 'purchases' | 'transfers' | 'assignments' | 'expenditures' }) {
  const config = { purchases: { title: 'Purchases', kicker: 'Movement / inbound stock', detail: 'Record and review stock received into an operating base.', button: 'Record purchase' }, transfers: { title: 'Transfers', kicker: 'Movement / cross-base', detail: 'Initiate and review controlled movements between bases.', button: 'Initiate transfer' }, assignments: { title: 'Assignments', kicker: 'Movement / issued stock', detail: 'Assign available assets to named personnel.', button: 'Assign stock' }, expenditures: { title: 'Expenditures', kicker: 'Movement / consumed stock', detail: 'Record consumed stock with an auditable reason.', button: 'Record expenditure' } }[kind];
  const [open, setOpen] = useState(false); const [base, setBase] = useState(''); const [status, setStatus] = useState('');
  const bases = useListBases(); const equipment = useListEquipmentTypes();
  const baseId = base ? Number(base) : undefined;
  const purchases = useListPurchases(kind === 'purchases' ? { ...(baseId ? { baseId } : {}) } : undefined, { query: { enabled: kind === 'purchases', queryKey: getListPurchasesQueryKey(kind === 'purchases' ? { ...(baseId ? { baseId } : {}) } : undefined) } });
  const transfers = useListTransfers(kind === 'transfers' ? { ...(baseId ? { baseId } : {}), ...(status ? { status: status as any } : {}) } : undefined, { query: { enabled: kind === 'transfers', queryKey: getListTransfersQueryKey(kind === 'transfers' ? { ...(baseId ? { baseId } : {}), ...(status ? { status: status as any } : {}) } : undefined) } });
  const assignments = useListAssignments(kind === 'assignments' ? { ...(baseId ? { baseId } : {}) } : undefined, { query: { enabled: kind === 'assignments', queryKey: getListAssignmentsQueryKey(kind === 'assignments' ? { ...(baseId ? { baseId } : {}) } : undefined) } });
  const expenditures = useListExpenditures(kind === 'expenditures' ? { ...(baseId ? { baseId } : {}) } : undefined, { query: { enabled: kind === 'expenditures', queryKey: getListExpendituresQueryKey(kind === 'expenditures' ? { ...(baseId ? { baseId } : {}) } : undefined) } });
  const query = kind === 'purchases' ? purchases : kind === 'transfers' ? transfers : kind === 'assignments' ? assignments : expenditures;
  const retry = () => query.refetch();
  return <PageFrame><SectionHeading kicker={config.kicker} title={config.title} detail={config.detail} action={<Button data-testid={`button-open-${kind}-form`} onClick={() => setOpen(true)}><FilePlus2 size={15} />{config.button}</Button>} /><div className="mb-5 flex flex-wrap items-end gap-3 rounded-md border border-border bg-card p-3"><SelectField label="Base" value={base} onChange={setBase} options={(bases.data || []).map(b => ({ value: String(b.id), label: b.name }))} placeholder="All bases" />{kind === 'transfers' && <SelectField label="Status" value={status} onChange={setStatus} options={(Object.values(TransferStatus) as string[]).map(s => ({ value: s, label: s.replace('_', ' ') }))} placeholder="All statuses" />}<span className="pb-2 font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">{query.data?.length || 0} records in scope</span></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={retry} /> : query.data?.length ? <RecordTable kind={kind} data={query.data as any[]} /> : <EmptyState title={`No ${kind} recorded`} detail={`Create the first ${kind.slice(0, -1)} record to establish a traceable movement.`} />}{open && <RecordModal kind={kind} bases={bases.data || []} equipment={equipment.data || []} onClose={() => setOpen(false)} onDone={() => { setOpen(false); queryClient.invalidateQueries({ queryKey: query.queryKey }); }} />}</PageFrame>;
}
function TransferStatusControl({ transfer }: { transfer: any }) { const mutation = useUpdateTransferStatus(); const [next, setNext] = useState(transfer.status); const commit = () => { if (next !== transfer.status) mutation.mutate({ id: transfer.id, data: { status: next } }); }; return <div className="flex items-center gap-1"><select data-testid={`select-transfer-status-${transfer.id}`} value={next} onChange={e => setNext(e.target.value)} className="h-7 rounded border border-input bg-card px-1 text-[10px] font-bold uppercase"><option value={TransferStatus.PENDING}>Pending</option><option value={TransferStatus.IN_TRANSIT}>In transit</option><option value={TransferStatus.COMPLETED}>Completed</option><option value={TransferStatus.CANCELLED}>Cancelled</option></select><Button data-testid={`button-update-transfer-${transfer.id}`} variant="ghost" onClick={commit} disabled={mutation.isPending || next === transfer.status} className="h-7 px-1.5 text-primary"><RefreshCw size={12} className={mutation.isPending ? 'animate-spin' : ''} /></Button></div>; }
function RecordTable({ kind, data }: { kind: string; data: any[] }) { if (kind === 'purchases') return <DataTable columns={['Base', 'Equipment', 'Category', 'Quantity', 'Purchase date', 'Created by']} rows={data.map(x => <tr key={x.id}><td className="font-bold">{x.baseName}</td><td>{x.equipmentName}</td><td><CategoryBadge value={x.category} /></td><td className="font-mono-ui font-bold text-primary">{x.quantity}</td><td>{dateOnly(x.purchaseDate)}</td><td className="text-muted-foreground">{x.createdBy}</td></tr>)} />; if (kind === 'transfers') return <DataTable columns={['Route', 'Equipment', 'Qty', 'Status', 'Update', 'Initiated by', 'Timestamp']} rows={data.map(x => <tr key={x.id}><td className="font-bold">{x.sourceBaseName} <span className="mx-1 text-primary">→</span> {x.destinationBaseName}</td><td>{x.equipmentName}</td><td className="font-mono-ui font-bold text-primary">{x.quantity}</td><td><StatusBadge value={x.status} /></td><td><TransferStatusControl transfer={x} /></td><td>{x.initiatedBy}</td><td>{fmt(x.timestamp)}</td></tr>)} />; if (kind === 'assignments') return <DataTable columns={['Base', 'Equipment', 'Personnel', 'Qty', 'Assigned by', 'Assigned at']} rows={data.map(x => <tr key={x.id}><td className="font-bold">{x.baseName}</td><td>{x.equipmentName}</td><td>{x.personnelName}</td><td className="font-mono-ui font-bold text-primary">{x.quantity}</td><td>{x.assignedBy}</td><td>{fmt(x.assignedAt)}</td></tr>)} />; return <DataTable columns={['Base', 'Equipment', 'Quantity', 'Reason', 'Recorded by', 'Expended at']} rows={data.map(x => <tr key={x.id}><td className="font-bold">{x.baseName}</td><td>{x.equipmentName}</td><td className="font-mono-ui font-bold text-chart-3">{x.quantity}</td><td>{x.reason}</td><td>{x.recordedBy}</td><td>{fmt(x.expendedAt)}</td></tr>)} />; }
function StatusBadge({ value }: { value: string }) { return <span className={cn('inline-flex rounded-sm px-2 py-1 font-mono-ui text-[9px] uppercase tracking-[.1em]', value === 'COMPLETED' ? 'bg-chart-4/10 text-chart-4' : value === 'CANCELLED' ? 'bg-destructive/10 text-destructive' : 'bg-accent/20 text-foreground')}>{value.replace('_', ' ')}</span>; }

function RecordModal({ kind, bases, equipment, onClose, onDone }: { kind: 'purchases' | 'transfers' | 'assignments' | 'expenditures'; bases: Base[]; equipment: EquipmentType[]; onClose: () => void; onDone: () => void }) {
  const [form, setForm] = useState<Record<string, string>>({ baseId: '', destinationBaseId: '', sourceBaseId: '', equipmentTypeId: '', quantity: '', purchaseDate: new Date().toISOString().slice(0, 10), personnelName: '', reason: '' }); const [error, setError] = useState('');
  const purchase = useCreatePurchase(); const transfer = useCreateTransfer(); const assignment = useCreateAssignment(); const expenditure = useCreateExpenditure();
  const set = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); const quantity = Number(form.quantity); if (!quantity || quantity < 1) return setError('Quantity must be at least 1.'); if (kind === 'purchases') purchase.mutate({ data: { baseId: Number(form.baseId), equipmentTypeId: Number(form.equipmentTypeId), quantity, purchaseDate: form.purchaseDate } }, { onSuccess: onDone, onError: err => setError((err as Error).message) }); if (kind === 'transfers') transfer.mutate({ data: { sourceBaseId: Number(form.sourceBaseId), destinationBaseId: Number(form.destinationBaseId), equipmentTypeId: Number(form.equipmentTypeId), quantity } }, { onSuccess: onDone, onError: err => setError((err as Error).message) }); if (kind === 'assignments') assignment.mutate({ data: { baseId: Number(form.baseId), equipmentTypeId: Number(form.equipmentTypeId), personnelName: form.personnelName, quantity } }, { onSuccess: onDone, onError: err => setError((err as Error).message) }); if (kind === 'expenditures') expenditure.mutate({ data: { baseId: Number(form.baseId), equipmentTypeId: Number(form.equipmentTypeId), quantity, reason: form.reason } }, { onSuccess: onDone, onError: err => setError((err as Error).message) }); };
  const pending = purchase.isPending || transfer.isPending || assignment.isPending || expenditure.isPending;
  return <Modal title={`Record ${kind.slice(0, -1)}`} eyebrow="New movement" onClose={onClose}><form onSubmit={submit} className="grid gap-4">{kind === 'transfers' ? <div className="grid gap-4 sm:grid-cols-2"><SelectField label="Source base" value={form.sourceBaseId} onChange={v => set('sourceBaseId', v)} options={bases.map(b => ({ value: String(b.id), label: b.name }))} /><SelectField label="Destination base" value={form.destinationBaseId} onChange={v => set('destinationBaseId', v)} options={bases.map(b => ({ value: String(b.id), label: b.name }))} /></div> : <SelectField label="Base" value={form.baseId} onChange={v => set('baseId', v)} options={bases.map(b => ({ value: String(b.id), label: b.name }))} />}<SelectField label="Equipment type" value={form.equipmentTypeId} onChange={v => set('equipmentTypeId', v)} options={equipment.map(x => ({ value: String(x.id), label: `${x.name} / ${categoryLabel(x.category)}` }))} /><Field label="Quantity"><input data-testid="input-quantity" required type="number" min="1" value={form.quantity} onChange={e => set('quantity', e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 font-mono-ui text-sm outline-none focus:border-primary" /></Field>{kind === 'purchases' && <Field label="Purchase date"><input data-testid="input-purchase-date" required type="date" value={form.purchaseDate} onChange={e => set('purchaseDate', e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field>}{kind === 'assignments' && <Field label="Personnel name"><input data-testid="input-personnel-name" required value={form.personnelName} onChange={e => set('personnelName', e.target.value)} placeholder="e.g. Lt. A. Volkov" className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field>}{kind === 'expenditures' && <Field label="Reason"><textarea data-testid="input-expenditure-reason" required value={form.reason} onChange={e => set('reason', e.target.value)} placeholder="Training exercise, maintenance, loss…" className="min-h-20 rounded-md border border-input bg-card p-3 text-sm outline-none focus:border-primary" /></Field>}{error && <p data-testid="status-form-error" className="rounded-md bg-destructive/10 p-3 text-xs font-bold text-destructive">{error}</p>}<div className="flex justify-end gap-2 border-t border-border pt-4"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-form">Cancel</Button><Button type="submit" disabled={pending} data-testid="button-submit-form">{pending ? 'Submitting…' : 'Commit record'}</Button></div></form></Modal>;
}

function Audit() { const q = useListAuditLogs(); return <PageFrame><SectionHeading kicker="Control / traceability" title="Audit trail" detail="Immutable security and inventory events across the operating system." /><div className="mb-5 grid gap-3 sm:grid-cols-3"><Metric label="Event stream" value={q.data?.length || 0} accent="accent" /><Metric label="Window" value="All time" /><Metric label="Integrity" value="Verified" accent="green" /></div>{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : q.data?.length ? <div className="space-y-2">{q.data.map(x => <div data-testid={`row-audit-${x.id}`} key={x.id} className="flex gap-4 rounded-md border border-border bg-card p-4"><div className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-full bg-primary/10 text-primary"><KeyRound size={14} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-baseline justify-between gap-2"><p className="text-sm font-bold">{x.action} <span className="font-normal text-muted-foreground">on {x.entityType}{x.entityId ? ` #${x.entityId}` : ''}</span></p><time className="font-mono-ui text-[10px] text-muted-foreground">{fmt(x.createdAt)}</time></div><p className="mt-1 text-xs text-muted-foreground">{x.details}</p><p className="mt-2 font-mono-ui text-[10px] uppercase tracking-[.12em] text-primary">{x.username} / user {x.userId}</p></div></div>)}</div> : <EmptyState title="No audit events" detail="System events will appear when operations begin." />}</PageFrame>; }

function AdminBases() { const q = useListBases(); const [open, setOpen] = useState(false); const create = useCreateBase(); const update = useUpdateBase(); const del = useDeleteBase(); const [editing, setEditing] = useState<Base | null>(null); const [name, setName] = useState(''); const [location, setLocation] = useState(''); const save = (e: FormEvent) => { e.preventDefault(); const data = { name, location }; const done = () => { setOpen(false); setEditing(null); queryClient.invalidateQueries({ queryKey: getListBasesQueryKey() }); }; editing ? update.mutate({ id: editing.id, data }, { onSuccess: done }) : create.mutate({ data }, { onSuccess: done }); }; const begin = (base?: Base) => { setEditing(base || null); setName(base?.name || ''); setLocation(base?.location || ''); setOpen(true); }; return <PageFrame><SectionHeading kicker="Administration / locations" title="Bases" detail="Manage the operating locations and their current readiness posture." action={<Button data-testid="button-add-base" onClick={() => begin()}><Building2 size={15} />Add base</Button>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : q.data?.length ? <DataTable columns={['Base', 'Location', 'Asset count', 'Readiness', 'Actions']} rows={q.data.map(x => <tr key={x.id}><td className="font-bold">{x.name}</td><td>{x.location}</td><td className="font-mono-ui">{x.assetCount ?? 0}</td><td><span className="font-mono-ui text-chart-4">{x.readiness ?? 0}%</span></td><td className="flex gap-1"><Button variant="ghost" data-testid={`button-edit-base-${x.id}`} onClick={() => begin(x)}><Settings2 size={14} />Edit</Button><Button variant="ghost" data-testid={`button-delete-base-${x.id}`} onClick={() => { if (confirm(`Delete ${x.name}?`)) del.mutate({ id: x.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListBasesQueryKey() }) }); }} className="text-destructive"><X size={14} /></Button></td></tr>)} /> : <EmptyState title="No bases configured" detail="Add the first operating location to establish the network." />}{open && <Modal title={editing ? 'Edit base' : 'Add base'} eyebrow="Location registry" onClose={() => setOpen(false)}><form onSubmit={save} className="grid gap-4"><Field label="Base name"><input data-testid="input-base-name" required value={name} onChange={e => setName(e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><Field label="Location"><input data-testid="input-base-location" required value={location} onChange={e => setLocation(e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><Button disabled={create.isPending || update.isPending} type="submit" data-testid="button-submit-base">{editing ? 'Save changes' : 'Create base'}</Button></form></Modal>}</PageFrame>; }

function AdminEquipment() { const q = useListEquipmentTypes(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<EquipmentType | null>(null); const [name, setName] = useState(''); const [category, setCategory] = useState(''); const [unit, setUnit] = useState(''); const create = useCreateEquipmentType(); const update = useUpdateEquipmentType(); const del = useDeleteEquipmentType(); const begin = (x?: EquipmentType) => { setEditing(x || null); setName(x?.name || ''); setCategory(x?.category || ''); setUnit(x?.unit || ''); setOpen(true); }; const save = (e: FormEvent) => { e.preventDefault(); const data = { name, category: category as Category, unit }; const done = () => { setOpen(false); queryClient.invalidateQueries({ queryKey: getListEquipmentTypesQueryKey() }); }; editing ? update.mutate({ id: editing.id, data }, { onSuccess: done }) : create.mutate({ data }, { onSuccess: done }); }; return <PageFrame><SectionHeading kicker="Administration / catalog" title="Equipment catalog" detail="Maintain the canonical names, categories, and units used by every movement record." action={<Button data-testid="button-add-equipment" onClick={() => begin()}><PackagePlus size={15} />Add equipment</Button>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : q.data?.length ? <DataTable columns={['Equipment type', 'Category', 'Unit', 'Actions']} rows={q.data.map(x => <tr key={x.id}><td className="font-bold">{x.name}</td><td><CategoryBadge value={x.category} /></td><td className="font-mono-ui">{x.unit || 'unit'}</td><td className="flex gap-1"><Button variant="ghost" data-testid={`button-edit-equipment-${x.id}`} onClick={() => begin(x)}><Settings2 size={14} />Edit</Button><Button variant="ghost" data-testid={`button-delete-equipment-${x.id}`} onClick={() => { if (confirm(`Delete ${x.name}?`)) del.mutate({ id: x.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListEquipmentTypesQueryKey() }) }); }} className="text-destructive"><X size={14} /></Button></td></tr>)} /> : <EmptyState title="Catalog is empty" detail="Add equipment types before recording stock movement." />}{open && <Modal title={editing ? 'Edit equipment' : 'Add equipment'} eyebrow="Catalog registry" onClose={() => setOpen(false)}><form onSubmit={save} className="grid gap-4"><Field label="Equipment name"><input data-testid="input-equipment-name" required value={name} onChange={e => setName(e.target.value)} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><SelectField label="Category" value={category} onChange={setCategory} options={(Object.values(Category) as string[]).map(x => ({ value: x, label: categoryLabel(x) }))} /><Field label="Unit"><input data-testid="input-equipment-unit" value={unit} onChange={e => setUnit(e.target.value)} placeholder="each, rounds, litres…" className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><Button disabled={create.isPending || update.isPending} type="submit" data-testid="button-submit-equipment">{editing ? 'Save changes' : 'Create equipment'}</Button></form></Modal>}</PageFrame>; }

function AdminUsers() { const q = useListUsers(); const bases = useListBases(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<User | null>(null); const [form, setForm] = useState<{ username: string; password: string; role: Role; baseId: string }>({ username: '', password: '', role: Role.LOGISTICS_OFFICER, baseId: '' }); const create = useCreateUser(); const update = useUpdateUser(); const del = useDeleteUser(); const begin = (x?: User) => { setEditing(x || null); setForm({ username: x?.username || '', password: '', role: x?.role || Role.LOGISTICS_OFFICER, baseId: x?.baseId ? String(x.baseId) : '' }); setOpen(true); }; const save = (e: FormEvent) => { e.preventDefault(); const done = () => { setOpen(false); queryClient.invalidateQueries({ queryKey: getListUsersQueryKey() }); }; if (editing) update.mutate({ id: editing.id, data: { username: form.username, ...(form.password ? { password: form.password } : {}), role: form.role, baseId: form.baseId ? Number(form.baseId) : null } }, { onSuccess: done }); else create.mutate({ data: { username: form.username, password: form.password, role: form.role, baseId: form.baseId ? Number(form.baseId) : null } }, { onSuccess: done }); }; return <PageFrame><SectionHeading kicker="Administration / access" title="Users" detail="Control operator access, role boundaries, and base assignments." action={<Button data-testid="button-add-user" onClick={() => begin()}><UserCog size={15} />Add user</Button>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : q.data?.length ? <DataTable columns={['Operator', 'Role', 'Base', 'Last active', 'Actions']} rows={q.data.map(x => <tr key={x.id}><td className="font-bold">{x.username}</td><td><span className="font-mono-ui text-[10px] uppercase text-primary">{x.role.replaceAll('_', ' ')}</span></td><td>{x.baseName || 'Network-wide'}</td><td className="font-mono-ui text-muted-foreground">{fmt(x.lastActiveAt)}</td><td className="flex gap-1"><Button variant="ghost" data-testid={`button-edit-user-${x.id}`} onClick={() => begin(x)}><Settings2 size={14} />Edit</Button><Button variant="ghost" data-testid={`button-delete-user-${x.id}`} onClick={() => { if (confirm(`Delete ${x.username}?`)) del.mutate({ id: x.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListUsersQueryKey() }) }); }} className="text-destructive"><X size={14} /></Button></td></tr>)} /> : <EmptyState title="No operators" detail="Create an operator account to staff the command network." />}{open && <Modal title={editing ? 'Edit operator' : 'Add operator'} eyebrow="Access control" onClose={() => setOpen(false)}><form onSubmit={save} className="grid gap-4"><Field label="Username"><input data-testid="input-user-username" required minLength={3} value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><Field label={editing ? 'New password' : 'Password'} hint={editing ? 'Leave blank to keep current password.' : 'Minimum 8 characters'}><input data-testid="input-user-password" required={!editing} minLength={editing ? 0 : 8} type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} className="h-10 rounded-md border border-input bg-card px-3 text-sm outline-none focus:border-primary" /></Field><SelectField label="Role" value={form.role} onChange={v => setForm({ ...form, role: v as Role })} options={(Object.values(Role) as string[]).map(x => ({ value: x, label: x.replaceAll('_', ' ') }))} /><SelectField label="Base assignment" value={form.baseId} onChange={v => setForm({ ...form, baseId: v })} options={(bases.data || []).map(x => ({ value: String(x.id), label: x.name }))} placeholder="Network-wide" /><Button type="submit" data-testid="button-submit-user">{editing ? 'Save changes' : 'Create operator'}</Button></form></Modal>}</PageFrame>; }

function Login() { const [, setLocation] = useLocation(); const login = useLogin(); const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const submit = (e: FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { username, password } }, { onSuccess: session => { queryClient.setQueryData(['/api/auth/me'], session.user); setLocation('/'); }, onError: err => setError((err as Error).message || 'Credentials rejected') }); }; return <div className="scanline grid min-h-[100dvh] bg-sidebar text-sidebar-foreground md:grid-cols-[1.15fr_.85fr]"><div className="panel-grid relative hidden overflow-hidden border-r border-sidebar-border p-10 md:flex md:flex-col md:justify-between"><div className="relative z-10 flex items-center gap-3"><span className="grid h-10 w-10 place-items-center bg-sidebar-primary text-sidebar-primary-foreground"><Command size={22} /></span><div><strong className="font-display text-3xl uppercase">Kristallball</strong><p className="font-mono-ui text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/50">Asset operations</p></div></div><div className="relative z-10 max-w-xl"><p className="font-mono-ui text-xs uppercase tracking-[.22em] text-sidebar-primary">Restricted command system</p><h1 className="mt-4 font-display text-7xl uppercase leading-[.82]">Know your<br /><span className="text-sidebar-primary">stock.</span><br />Move with intent.</h1><p className="mt-7 max-w-md text-sm leading-6 text-sidebar-foreground/55">A single operational picture for commanders and logistics teams across every base.</p></div><div className="relative z-10 flex items-center gap-3 font-mono-ui text-[10px] uppercase tracking-[.15em] text-sidebar-foreground/45"><span className="h-2 w-2 rounded-full bg-sidebar-primary" /> Encrypted session / Network 04</div><div className="absolute -bottom-32 -right-20 h-96 w-96 rounded-full border-[40px] border-sidebar-primary/10" /></div><div className="flex items-center justify-center p-5 sm:p-10"><div className="w-full max-w-md"><div className="mb-10 md:hidden"><span className="grid h-10 w-10 place-items-center bg-sidebar-primary text-sidebar-primary-foreground"><Command size={22} /></span><h1 className="mt-4 font-display text-4xl uppercase">Kristallball</h1><p className="font-mono-ui text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/50">Asset operations</p></div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-sidebar-primary">Operator authentication</p><h2 className="mt-2 font-display text-5xl uppercase leading-none">Login</h2><p className="mt-3 text-sm text-sidebar-foreground/55">Enter your issued credentials to access command operations.</p><form onSubmit={submit} className="mt-8 grid gap-5"><Field label="Username"><input data-testid="input-login-username" required value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" className="h-11 rounded-md border border-sidebar-border bg-sidebar-accent/50 px-3 text-sm text-sidebar-foreground outline-none placeholder:text-sidebar-foreground/35 focus:border-sidebar-primary" /></Field><Field label="Password"><input data-testid="input-login-password" required type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" className="h-11 rounded-md border border-sidebar-border bg-sidebar-accent/50 px-3 text-sm text-sidebar-foreground outline-none focus:border-sidebar-primary" /></Field>{error && <p data-testid="status-login-error" className="rounded-md border border-destructive/40 bg-destructive/10 p-3 text-xs font-bold text-red-200">{error}</p>}<Button
  type="submit"
  disabled={login.isPending}
  data-testid="button-login"
  className="mt-1 h-11 text-white"
>
  {login.isPending ? 'Signing in…' : 'Sign in'}
</Button></form><div className="mt-10 border-t border-sidebar-border pt-5 font-mono-ui text-[9px] uppercase tracking-[.14em] text-sidebar-foreground/35">Authorized personnel only · All activity is logged</div></div></div></div>; }

function ProtectedRouter() { const current = useGetCurrentUser({ query: { queryKey: ['/api/auth/me'], retry: (failureCount, error) => !isUnauthorizedError(error) && failureCount < 2 } }); const [, setLocation] = useLocation(); const unauthorized = current.isError && isUnauthorizedError(current.error); useEffect(() => { if (unauthorized) setLocation('/login'); }, [setLocation, unauthorized]); if (current.isLoading) return <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="w-64"><LoadingState label="Establishing secure session" /></div></div>; if (unauthorized) return <Login />; if (current.isError) return <div className="grid min-h-[100dvh] place-items-center bg-background p-5"><div className="w-full max-w-xl"><ErrorState onRetry={() => current.refetch()} label="Unable to establish secure session" /></div></div>; if (!current.data) return <Login />; return <Shell user={current.data}><Switch><Route path="/" component={Overview} /><Route path="/inventory" component={Inventory} /><Route path="/purchases" component={() => <RecordPage kind="purchases" />} /><Route path="/transfers" component={() => <RecordPage kind="transfers" />} /><Route path="/assignments" component={() => <RecordPage kind="assignments" />} /><Route path="/expenditures" component={() => <RecordPage kind="expenditures" />} /><Route path="/audit" component={Audit} /><Route path="/admin/users" component={AdminUsers} /><Route path="/admin/bases" component={AdminBases} /><Route path="/admin/equipment" component={AdminEquipment} /><Route component={() => <div className="py-20 text-center"><Siren className="mx-auto text-destructive" /><h1 className="mt-4 font-display text-5xl uppercase">Route not found</h1><Link href="/" className="mt-4 inline-block text-sm font-bold text-primary">Return to overview</Link></div>} /></Switch></Shell>; }
function Router() { const [isLogin] = useRoute('/login'); return isLogin ? <Login /> : <ProtectedRouter />; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></QueryClientProvider>; }
export default App;
